describe('Rate Limit Error Handling on Form Submission', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display rate limit error when submitting form too many times', () => {
    // First successful submission
    cy.get('[data-testid="form-input"]').type('test@example.com');
    cy.get('[data-testid="form-password"]').type('password123');
    cy.get('[data-testid="submit-button"]').click();
    cy.intercept('POST', '/api/submit').as('formSubmit');
    cy.wait('@formSubmit');
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Second submission (should succeed)
    cy.get('[data-testid="form-input"]').clear().type('another@example.com');
    cy.get('[data-testid="form-password"]').clear().type('password123');
    cy.get('[data-testid="submit-button"]').click();
    cy.intercept('POST', '/api/submit').as('formSubmit2');
    cy.wait('@formSubmit2');
    cy.get('[data-testid="success-message"]').should('be.visible');

    // Third submission (should trigger rate limit error)
    cy.get('[data-testid="form-input"]').clear().type('third@example.com');
    cy.get('[data-testid="form-password"]').clear().type('password123');
    cy.get('[data-testid="submit-button"]').click();
    cy.intercept('POST', '/api/submit', {
      statusCode: 429,
      body: { error: 'Too many requests', retryAfter: 60 }
    }).as('rateLimitError');
    cy.wait('@rateLimitError');

    // Verify rate limit error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Too many requests');
    cy.get('[data-testid="error-message"]').should('contain', 'Please try again in 60 seconds');

    // Verify form is still visible and not disabled
    cy.get('[data-testid="form-input"]').should('be.visible');
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
  });

  it('should disable submit button and show error when rate limit is exceeded', () => {
    // First submission (should succeed)
    cy.get('[data-testid="form-input"]').type('first@example.com');
    cy.get('[data-testid="form-password"]').type('password123');
    cy.get('[data-testid="submit-button"]').click();
    cy.intercept('POST', '/api/submit').as('formSubmit1');
    cy.wait('@formSubmit1');
    cy.get('[data-testid="success-message"]').should('be.visible');

    // Second submission (should succeed)
    cy.get('[data-testid="form-input"]').clear().type('second@example.com');
    cy.get('[data-testid="form-password"]').clear().type('password123');
    cy.get('[data-testid="submit-button"]').click();
    cy.intercept('POST', '/api/submit').as('formSubmit2');
    cy.wait('@formSubmit2');
    cy.get('[data-testid="success-message"]').should('be.visible');

    // Third submission (should trigger rate limit error)
    cy.get('[data-testid="form-input"]').clear().type('third@example.com');
    cy.get('[data-testid="form-password"]').clear().type('password123');
    cy.get('[data-testid="submit-button"]').click();
    cy.intercept('POST', '/api/submit', {
      statusCode: 429,
      body: { error: 'Too many requests', retryAfter: 60 }
    }).as('rateLimitError');
    cy.wait('@rateLimitError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Rate limit exceeded');

    // Verify submit button is disabled after rate limit error
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Verify retry timer is visible
    cy.get('[data-testid="retry-timer"]').should('be.visible');
    cy.get('[data-testid="retry-timer"]').should('contain', '60 seconds');

    // Verify form fields are still populated with last attempt data
    cy.get('[data-testid="form-input"]').should('have.value', 'third@example.com');
    cy.get('[data-testid="form-password"]').should('have.value', 'password123');
  });
});
